def build_planning_stages() -> list[dict[str, str]]:
    keys = (
        "title", "label", "intro", "purpose", "why", "method", "exercise",
        "criteria", "watch_for", "output", "completion",
    )
    return [dict(zip(keys, row)) for row in _STAGE_GUIDES]


